def get_first_element(items):        # O(1) - constant time, one operation
    return items[0]

def sum_all_elements(items):         # O(n) - linear time, grows with input size
    total = 0
    for item in items:
        total += item
    return total

def has_duplicate_pair(items):       # O(n^2) - nested loop over every pair
    for i in range(len(items)):
        for j in range(i + 1, len(items)):
            if items[i] == items[j]:
                return True
    return False

class Node:
    def __init__(self, value):
        self.value = value
        self.next = None

class LinkedList:
    def __init__(self):
        self.head = None

    def append(self, value):
        new_node = Node(value)
        if not self.head:
            self.head = new_node
            return
        current = self.head
        while current.next:
            current = current.next
        current.next = new_node

    def to_list(self):
        result, current = [], self.head
        while current:
            result.append(current.value)
            current = current.next
        return result

ll = LinkedList()
ll.append(1); ll.append(2); ll.append(3)
print(ll.to_list())   # [1, 2, 3]

