def has_path(graph, start, end, visited=None):
    visited = visited or set()
    if start == end:
        return True
    visited.add(start)
    for neighbor in graph[start]:
        if neighbor not in visited and has_path(graph, neighbor, end, visited):
            return True
    return False

print(has_path(graph, "A", "D"))   # True

